gPq(){return"Away (subdominant)"},
gPp(){return"Tension (dominant)"},
gb0z(){return"Home"},
gb0y(){return"Away"},
gb0x(){return"Tension"},
gaPX(){return"Harmony"},
gaQ6(){return"Analyse the harmony"},
gD_(){return"Inspect (tap a note)"},
gaPW(){return"Form"},
gaPS(){return"Circle of fifths"},
gaQ4(){return"Tension"},
gah_(){return"Voice leading"},
gaQ5(){return"No parallel 5ths or 8ves \u2713"},
gaQ2(){return"Parallel fifths"},
gaQ3(){return"Parallel octaves"},
gagZ(){return"Non-chord tones"},
gahF(){return"perfect cadence"},
gahH(){return"half cadence"},
gahI(){return"plagal cadence"},
gahG(){return"deceptive cadence"},
